import math
CM1_TO_THz = 29.9792458  # 1 cm^-1 = 29.979 GHz*... = 0.029979 THz -> period conversion below
def period_fs(cm1): return 1e15/(cm1*CM1_TO_THz*1e12)
dt=2.0  # illustrative full-rate frame interval, fs
modes=[50.0,100.0,200.0]
Tref=period_fs(100.0)
print("dt_full(illustrative)=%.1f fs ; T(100cm-1)=%.1f fs  T(50)=%.1f T(200)=%.1f"%(dt,period_fs(100),period_fs(50),period_fs(200)))
print("Nyquist-safe dt for f_max=200cm-1: %.1f fs ; curvature-safe (T/10): %.1f fs"%(period_fs(200)/2, period_fs(200)/10))
print()
print(" r*    k     tau_fs   tau_ps | samples/period for each mode (50,100,200 cm-1) | aliased apparent freq (cm-1) of each mode")
for r in [16,8,4,2,1,0.2,0.02]:
    k=max(1,round(Tref/(r*dt))); tau=k*dt
    row=[]
    for m in modes:
        T=period_fs(m); fs=1.0/tau
        n=round((1.0/T)/fs)            # nearest folding order
        f_alias=abs(1.0/T - n*fs)      # THz-ish units consistent (1/fs)
        row.append("n=%+d fa=%6.1f"%(n,f_alias*1e15/ (CM1_TO_THz*1e12)/1.0 if False else f_alias*1e15/ (CM1_TO_THz*1e12)*1e0))
    # convert: f in 1/fs -> Hz = f*1e15 ; cm-1 = Hz/(c cm/s)=Hz/2.99792458e10
    rowconv=[]
    for m in modes:
        T=period_fs(m); fs=1.0/tau
        n=round((1.0/T)/fs); fa=abs(1.0/T-n*fs)
        cm=fa*1e15/2.99792458e10
        rowconv.append("%3d/%6.2f"%(n,cm))
    print(" %5.2f %6d %8.0f %7.2f | %s"%(r,k,tau,tau/1000.0," ".join(rowconv)))
